package com.pranaveda.media;

import java.util.Map;

import com.pranaveda.common.error.ApiException;
import com.pranaveda.common.error.StorageException;

import com.cloudinary.Cloudinary;
import com.cloudinary.utils.ObjectUtils;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

/**
 * Cloudinary-backed {@link StorageService} (architecture section 9). The only
 * class that depends on the Cloudinary SDK; everything else uses the interface.
 *
 * <p>Object keys are generated by the caller and always scoped to a folder, so
 * original filenames are never used as storage paths (agents.md 2.15). Uploads
 * overwrite their own public id, which makes profile-photo replacement atomic.
 */
@Service
public class CloudinaryStorageService implements StorageService {

    private static final Logger log = LoggerFactory.getLogger(CloudinaryStorageService.class);

    private final CloudinaryProperties properties;
    private volatile Cloudinary cloudinary; // built lazily so the app boots without credentials

    public CloudinaryStorageService(CloudinaryProperties properties) {
        this.properties = properties;
    }

    /**
     * The Cloudinary client is created on first use, not in the constructor, so
     * the application starts cleanly before credentials are supplied. A missing
     * configuration only surfaces when an upload is actually attempted - the
     * rest of the platform (auth, content, AI) keeps working without storage.
     */
    private Cloudinary client() {
        Cloudinary existing = cloudinary;
        if (existing != null) {
            return existing;
        }
        if (!properties.isConfigured()) {
            throw new StorageException(
                "Media storage is not configured. Set app.cloudinary.cloud-name / api-key / "
                    + "api-secret (or the CLOUDINARY_URL environment variable).");
        }
        synchronized (this) {
            if (cloudinary == null) {
                cloudinary = new Cloudinary(ObjectUtils.asMap(
                    "cloud_name", properties.cloudName(),
                    "api_key", properties.apiKey(),
                    "api_secret", properties.apiSecret(),
                    "secure", true));
            }
            return cloudinary;
        }
    }

    @Override
    public StoredMedia upload(byte[] bytes, String folder, String publicId, String resourceType) {
        String scopedId = combine(folder, publicId);
        try {
            @SuppressWarnings("unchecked")
            Map<String, Object> result = client().uploader().upload(
                bytes,
                ObjectUtils.asMap(
                    "public_id", scopedId,
                    "resource_type", resourceType,
                    "overwrite", true,
                    "invalidate", true));
            return toStoredMedia(result);
        } catch (ApiException ex) {
            throw ex;
        } catch (Exception ex) {
            log.warn("Cloudinary upload failed for publicId={} resourceType={}", scopedId, resourceType, ex);
            throw new StorageException("Failed to store the uploaded file.", ex);
        }
    }

    @Override
    public void delete(String publicId, String resourceType) {
        if (!properties.isConfigured()) {
            return; // nothing was ever uploaded
        }
        try {
            client().uploader().destroy(publicId, ObjectUtils.asMap(
                "resource_type", resourceType,
                "invalidate", true));
        } catch (Exception ex) {
            // Deletion is best-effort: a missing object or transient error must
            // not fail a user-facing action. Logged for operator follow-up.
            log.warn("Cloudinary delete failed for publicId={} resourceType={}", publicId, resourceType, ex);
        }
    }

    private static StoredMedia toStoredMedia(Map<String, Object> result) {
        return new StoredMedia(
            str(result.get("public_id")),
            str(result.get("secure_url")),
            str(result.get("resource_type")),
            str(result.get("format")),
            longValue(result.get("bytes")),
            intValue(result.get("width")),
            intValue(result.get("height")),
            doubleValue(result.get("duration")));
    }

    private static String combine(String folder, String publicId) {
        if (folder == null || folder.isBlank()) {
            return publicId;
        }
        return folder.replaceAll("/+$", "") + "/" + publicId;
    }

    private static String str(Object value) {
        return value == null ? null : value.toString();
    }

    private static long longValue(Object value) {
        if (value instanceof Number number) {
            return number.longValue();
        }
        if (value instanceof String s && !s.isBlank()) {
            return (long) Double.parseDouble(s);
        }
        return 0L;
    }

    private static Integer intValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        if (value instanceof String s && !s.isBlank()) {
            return (int) Double.parseDouble(s);
        }
        return null;
    }

    private static Double doubleValue(Object value) {
        if (value instanceof Number number) {
            return number.doubleValue();
        }
        if (value instanceof String s && !s.isBlank()) {
            return Double.parseDouble(s);
        }
        return null;
    }
}
